lip-warn {\n  font-size: 11px;\n  line-height: 1.55;\n  color: var(--c-danger);\n  border-left: 2px solid var(--c-danger);\n  padding-left: 7px;\n}\n\n.qy-slip-actions {\n  display: flex;\n  gap: 6px;\n}\n\n.qy-slip-send {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.qy-link {\n  align-self: flex-start;\n  padding: 0;\n  border: none;\n  background: transparent;\n  font-family: inherit;\n  font-size: 10.5px;\n  color: var(--c-primary-soft);\n  border-bottom: 1px dashed var(--c-primary-soft);\n  cursor: pointer;\n}\n\n.qy-slip-text {\n  margin: 0;\n  padding: 7px 9px;\n  font-family: var(--font-body);\n  font-size: 11.5px;\n  line-height: 1.7;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  color: var(--c-text);\n  background: var(--c-surface);\n  border: 1px dashed var(--c-border);\n}\n\n.qy-btn {\n  font-family: inherit;\n  font-size: 11.5px;\n  padding: 3px 14px;\n  letter-spacing: 1px;\n  color: var(--c-primary);\n  background: var(--c-surface);\n  border: 1px solid var(--c-primary-soft);\n  cursor: pointer;\n  transition: all 160ms var(--ease-gentle);\n}\n\n.qy-btn:hover {\n  background: var(--c-surface-raised);\n  border-color: var(--c-primary);\n}\n\n.qy-btn:active {\n  transform: translateY(1px);\n}\n\n.qy-btn-primary {\n  color: var(--c-surface-raised);\n  background: var(--c-primary);\n  border-color: var(--c-primary);\n}\n\n.qy-btn-primary:hover {\n  color: var(--c-surface-raised);\n  background: var(--c-seal);\n  border-color: var(--c-seal);\n}\n"],"sourceRoot":""}]);
